async (page) => {
 const targets = ['cora.halvorsen','cora.matthieu','cora.romoli','barbara.ishii','hattie.brennan','hattie.matthieu','ida.castillo','jack.stokes','lettie.brennan','marguerite.miccinesi','mildred.lindqvist','mildred.halvorsen','nellie.jacobs'];
 const filter = page.locator('input[placeholder="Filter by name..."]');
 const log=[];
 for (let i=0;i<targets.length;i++) {
  const t=targets[i]; const [first,last]=t.split('.');
  const email=t+'@avaya.example';
  if (i>0) {
   await filter.fill(last); await page.waitForTimeout(1000);
   await page.getByRole('gridcell',{name:email,exact:true}).click(); await page.waitForTimeout(600);
  }
  const vals = await page.evaluate(()=>[...document.querySelectorAll('input')].map(i=>i.value).join('|'));
  if (!vals.includes(email) || !vals.includes('Avaya Inc.') || !vals.includes('Closed (lost)')) { log.push('SKIP '+t+' '+vals); break; }
  await page.getByRole('button',{name:'Delete'}).click(); await page.waitForTimeout(800);
  log.push('deleted '+t);
 }
 return log;
}

