async (page) => {
 await page.locator('input[placeholder="Filter by name..."]').fill(''); await page.waitForTimeout(1000);
 return await page.evaluate(async () => { const g=document.querySelector('vaadin-grid'); const seen=new Map(); for(let i=0;i<=g.size;i+=5){ g.scrollToIndex(i); await new Promise(r=>setTimeout(r,200)); const t=[...g.querySelectorAll('vaadin-grid-cell-content')].map(c=>c.innerText.trim()); for(let k=0;k+4<t.length;k++){ if(/@.*\.example$/.test(t[k+2])) seen.set(t[k+2],t.slice(k,k+5).join('|')); } } const all=[...seen.values()]; return {size:g.size, seen:all.length, closedAvaya: all.filter(s=>s.includes('Avaya')&&s.includes('Closed'))}; });
}

